  'update',
  $payload${"moduleId":"nerve-conduction","revisionType":"quiz","title":"Evaluación: Amplitud del SNAP","quizTopicId":"snap-amplitude","passScore":70,"maxAttempts":null,"shuffleQuestions":true,"shuffleOptions":true,"questions":[{"id":"snampa-q1","sortOrder":0,"type":"single","difficulty":"basic","stem":"¿Qué representa la amplitud del SNAP y por qué la lección desconfía del valor absoluto aislado?","options":[{"id":"snampa-q1-a","text":"El número de fibras sensitivas que siguen conduciendo. Varía mucho entre personas, así que el lado contralateral compara mejor que un número suelto.","isCorrect":true},{"id":"snampa-q1-b","text":"La mielina motora. Un valor único, sin el otro lado, cierra el diagnóstico.","isCorrect":false},{"id":"snampa-q1-c","text":"Solo la temperatura: si la amplitud es alta, el nervio está frío y hay que ignorar el otro lado.","isCorrect":false},{"id":"snampa-q1-d","text":"El número de unidades motoras, en milivoltios.","isCorrect":false}],"explanation":"La lección ata la amplitud a las fibras sensitivas funcionantes, recuerda que cae con la edad y que la comparación lado a lado vence al valor absoluto.\n\n📚 Referencia: Preston DC, Shapiro BE. Electromyography and Neuromuscular Disorders (4th ed). Elsevier (2021). https://www.elsevier.com/books/electromyography-and-neuromuscular-disorders/preston/978-0-323-66180-5","citations":[{"authors":"Preston DC, Shapiro BE","title":"Electromyography and Neuromuscular Disorders (4th ed)","journal":"Elsevier","year":2021,"url":"https://www.elsevier.com/books/electromyography-and-neuromuscular-disorders/preston/978-0-323-66180-5"}]},{"id":"snampa-q2","sortOrder":1,"type":"single","difficulty":"intermediate","stem":"Una mano a 27 °C muestra un SNAP más alto y más largo que el de la mano caliente. ¿Qué efecto térmico hay que usar al interpretarlo?","options":[{"id":"snampa-q2-a","text":"El frío aumenta amplitud y duración, además de alargar la latencia. No se lee esa amplitud alta como “más axones”.","isCorrect":true},{"id":"snampa-q2-b","text":"El frío borra la amplitud sensitiva, así que un SNAP alto demuestra que la mano estaba caliente.","isCorrect":false},{"id":"snampa-q2-c","text":"La temperatura no cambia la amplitud; solo cambia la velocidad.","isCorrect":false},{"id":"snampa-q2-d","text":"El frío convierte el SNAP de µV a mV.","isCorrect":false}],"explanation":"El capítulo de temperatura y la práctica estándar coinciden: el enfriamiento prolonga la latencia y aumenta amplitud y duración. Una frase suelta de esta lección dice lo contrario sobre la amplitud; no debe usarse para firmar un axonal “bajo” o “alto” en una mano fría. Preston describe ese aumento con el frío.\n\n📚 Referencia: Preston DC, Shapiro BE. Electromyography and Neuromuscular Disorders (4th ed). Elsevier (2021). https://www.elsevier.com/books/electromyography-and-neuromuscular-disorders/preston/978-0-323-66180-5","citations":[{"authors":"Preston DC, Shapiro BE","title":"Electromyography and Neuromuscular Disorders (4th ed)","journal":"Elsevier","year":2021,"url":"https://www.elsevier.com/books/electromyography-and-neuromuscular-disorders/preston/978-0-323-66180-5"}]},{"id":"snampa-q3","sortOrder":2,"type":"single","difficulty":"advanced","stem":"Paciente de 72 años. Sural derecho 6 µV, izquierdo 7 µV. ¿Cómo aplica la lección la edad y la comparación lateral?","options":[{"id":"snampa-q3-a","text":"La amplitud baja con la edad y aquí los dos lados se parecen. Una diferencia mayor del 50 % sería el hallazgo significativo, no el valor absoluto solo.","isCorrect":true},{"id":"snampa-q3-b","text":"6 µV a los 72 años es pérdida axonal segura, aunque el otro lado sea igual.","isCorrect":false},{"id":"snampa-q3-c","text":"Hay que exigir más de 25 µV a cualquier edad.","isCorrect":false},{"id":"snampa-q3-d","text":"Se informa el lado más alto y se descarta el más bajo.","isCorrect":false}],"explanation":"La lección dice que la amplitud cae con la edad y que la comparación lateral supera al absoluto. En el sural, después de los 60 años, 5–8 µV pueden ser normales.\n\n📚 Referencia: Chen S, Andary M, Buschbacher R, et al.. Electrodiagnostic reference values for upper and lower limb nerve conduction studies in adult populations. Muscle & Nerve (2016). https://doi.org/10.1002/mus.25203","citations":[{"authors":"Chen S, Andary M, Buschbacher R, et al.","title":"Electrodiagnostic reference values for upper and lower limb nerve conduction studies in adult populations","journal":"Muscle & Nerve","year":2016,"url":"https://doi.org/10.1002/mus.25203"}]},{"id":"snampa-q4","sortOrder":3,"type":"image_choice","difficulty":"intermediate","stem":"Dos SNAP del mismo nervio, misma distancia. El de la derecha mide unos 20 µV y el de la izquierda unos 6 µV, ambos a 10 µV/div. ¿Qué concluye la lección con esa asimetría?","options":[{"id":"snampa-q4-a","text":"La caída supera el 50 % frente al otro lado: es significativa, más que discutir el valor absoluto.","isCorrect":true},{"id":"snampa-q4-b","text":"6 µV es normal siempre, y el lado de 20 µV es el patológico por estar “demasiado alto”.","isCorrect":false},{"id":"snampa-q4-c","text":"Hay que promediar 13 µV e informarlo como único valor.","isCorrect":false},{"id":"snampa-q4-d","text":"La asimetría solo importa en el CMAP, no en el SNAP.","isCorrect":false}],"explanation":"6 µV es el 30 % de 20 µV: la diferencia relativa pasa del 50 %. La lección privilegia esa comparación.\n\n📚 Referencia: Chen S, Andary M, Buschbacher R, et al.. Electrodiagnostic reference values for upper and lower limb nerve conduction studies in adult populations. Muscle & Nerve (2016). https://doi.org/10.1002/mus.25203","citations":[{"authors":"Chen S, Andary M, Buschbacher R, et al.","title":"Electrodiagnostic reference values for upper and lower limb nerve conduction studies in adult populations","journal":"Muscle & Nerve","year":2016,"url":"https://doi.org/10.1002/mus.25203"}],"imageUrl":"/quiz-traces/snap-amplitude-snampa-q4.svg","imageAlt":"SNAP de baja amplitud, cerca de 6 µV, a 1 ms/div y 10 µV/div, inicio alrededor de 3.2 ms."}],"examQuestions":[{"module_id":"nerve-conduction","topic_id":"snap-amplitude","topic_name":"Amplitud del SNAP","island_name":"EMG","stem":"Mano derecha a 27 °C, SNAP mediano 45 µV y latencia pico 3.9 ms. La mano izquierda, a 33 °C, mide 22 µV y 3.1 ms. Alguien informa “axones de más” en la derecha.","difficulty":2,"is_critical":true,"findings":[{"type":"AMPL","label":"SNAP mediano derecho","value":"45 µV, pico 3.9 ms, piel 27 °C"},{"type":"AMPL","label":"SNAP mediano izquierdo","value":"22 µV, pico 3.1 ms, piel 33 °C"}],"options":[{"text":"Calentar la derecha. El frío infla la amplitud y alarga la latencia; 45 µV no significan más axones.","is_correct":true,"feedback":"La asimetría y la latencia larga se leen después de igualar la temperatura, no antes."},{"text":"Firmar hipertrofia axonal derecha por los 45 µV.","is_correct":false,"feedback":"El frío aumenta la amplitud de forma espuria."},{"text":"Informar pérdida axonal izquierda porque 22 µV es la mitad.","is_correct":false,"feedback":"El lado frío no es el denominador válido."},{"text":"Ignorar la temperatura: la amplitud sensitiva no cambia con ella.","is_correct":false,"feedback":"Cambia, y en el sentido de aumentar con el frío."}],"pearl":"Frío: latencia larga y amplitud alta. No llames a eso “más axones” ni desmielinización sin recalentar.","source_reference":"Preston DC, Shapiro BE. Electromyography and Neuromuscular Disorders (4th ed). Elsevier (2021). https://www.elsevier.com/books/electromyography-and-neuromuscular-disorders/preston/978-0-323-66180-5","tags":["nerve-conduction","snap-amplitude"],"status":"DRAFT"}]}$payload$::jsonb,
